#include "mavlink_pilot.h"

#include <cstring>
#include <print>

#include <arpa/inet.h>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <poll.h>
#include <sys/socket.h>
#include <unistd.h>

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Waddress-of-packed-member"
#include <ardupilotmega/mavlink.h>   // MAVLink C library generated by ArduPilot's build (see CMakeLists.txt)
#pragma GCC diagnostic pop

namespace drone
{
namespace
{
constexpr std::uint8_t kSys = 245, kComp = MAV_COMP_ID_ONBOARD_COMPUTER;   // us: a companion / pilot app
constexpr std::uint32_t kGuided = 4, kLand = 9;                               // ArduCopter custom modes
using clock = std::chrono::steady_clock;
}  // namespace

void MavlinkPilot::start(const PilotConfig& cfg, InputFn input)
{
    cfg_ = cfg;
    input_ = std::move(input);
    stop_ = false;
    thread_ = std::thread(&MavlinkPilot::run, this);
}

void MavlinkPilot::stop()
{
    stop_ = true;
    if (thread_.joinable()) thread_.join();
    if (fd_ >= 0) { ::close(fd_); fd_ = -1; }
}

PilotStatus MavlinkPilot::status() const
{
    std::lock_guard lk(mtx_);
    return st_;
}

bool MavlinkPilot::connect()
{
    fd_ = ::socket(AF_INET, SOCK_STREAM, 0);
    sockaddr_in a{};
    a.sin_family = AF_INET;
    a.sin_port = htons(static_cast<std::uint16_t>(cfg_.port));
    ::inet_pton(AF_INET, cfg_.host.c_str(), &a.sin_addr);
    if (::connect(fd_, reinterpret_cast<sockaddr*>(&a), sizeof(a)) != 0)
    {
        ::close(fd_);
        fd_ = -1;
        return false;
    }
    int one = 1;
    ::setsockopt(fd_, IPPROTO_TCP, TCP_NODELAY, &one, sizeof(one));
    return true;
}

void MavlinkPilot::send(const void* m)
{
    if (fd_ < 0) return;
    std::uint8_t buf[MAVLINK_MAX_PACKET_LEN];
    const auto n = mavlink_msg_to_send_buffer(buf, static_cast<const mavlink_message_t*>(m));
    if (::send(fd_, buf, n, MSG_NOSIGNAL) < 0) { ::close(fd_); fd_ = -1; }
}

void MavlinkPilot::command_long(std::uint16_t command, float p1, float p2, float p3, float p4, float p5,
                                float p6, float p7)
{
    mavlink_message_t m;
    mavlink_msg_command_long_pack(kSys, kComp, &m, target_sys_, target_comp_, command, 0, p1, p2, p3, p4, p5, p6, p7);
    send(&m);
}

void MavlinkPilot::set_mode(std::uint32_t custom_mode)
{
    command_long(MAV_CMD_DO_SET_MODE, MAV_MODE_FLAG_CUSTOM_MODE_ENABLED, static_cast<float>(custom_mode));
}

void MavlinkPilot::velocity(double fwd, double right, double down, double yaw_rate_cw)
{
    // velocity + yaw rate only: ignore position (bits 0-2), acceleration (6-8) and yaw angle (10)
    constexpr std::uint16_t kMask = 0b0000'0101'1100'0111;
    mavlink_message_t m;
    mavlink_msg_set_position_target_local_ned_pack(
        kSys, kComp, &m, 0, target_sys_, target_comp_, MAV_FRAME_BODY_OFFSET_NED, kMask, 0, 0, 0,
        static_cast<float>(fwd), static_cast<float>(right), static_cast<float>(down), 0, 0, 0, 0,
        static_cast<float>(yaw_rate_cw));
    send(&m);
}

void MavlinkPilot::handle(const void* p)
{
    const auto* m = static_cast<const mavlink_message_t*>(p);
    std::lock_guard lk(mtx_);
    switch (m->msgid)
    {
    case MAVLINK_MSG_ID_HEARTBEAT:
    {
        mavlink_heartbeat_t hb;
        mavlink_msg_heartbeat_decode(m, &hb);
        if (hb.autopilot == MAV_AUTOPILOT_INVALID) break;          // another GCS, not the vehicle
        target_sys_ = m->sysid;
        target_comp_ = m->compid;
        const bool armed = hb.base_mode & MAV_MODE_FLAG_SAFETY_ARMED;
        if (armed != st_.armed)
            std::print("[pilot] {}\n", armed ? "ARMED" : "disarmed");
        if (not armed) takeoff_sent_ = false;
        st_.armed = armed;
        st_.mode = hb.custom_mode;
        break;
    }
    case MAVLINK_MSG_ID_EXTENDED_SYS_STATE:
        st_.landed = mavlink_msg_extended_sys_state_get_landed_state(m);
        last_state_msg_ = clock::now();
        break;
    case MAVLINK_MSG_ID_GLOBAL_POSITION_INT:
        st_.rel_alt_m = mavlink_msg_global_position_int_get_relative_alt(m) / 1000.0;
        break;
    case MAVLINK_MSG_ID_COMMAND_ACK:
    {
        mavlink_command_ack_t ack;
        mavlink_msg_command_ack_decode(m, &ack);
        if (ack.result != MAV_RESULT_ACCEPTED)
            std::print("[pilot] command {} refused by the autopilot (MAV_RESULT {})\n", ack.command, ack.result);
        break;
    }
    case MAVLINK_MSG_ID_STATUSTEXT:
    {
        char text[MAVLINK_MSG_STATUSTEXT_FIELD_TEXT_LEN + 1] = {};
        mavlink_msg_statustext_get_text(m, text);
        std::print("[ardupilot] {}\n", text);                      // arming refusals, EKF state, crashes...
        break;
    }
    default:
        break;
    }
}

void MavlinkPilot::tick(const PilotInput& in, clock::time_point now)
{
    PilotStatus s;
    bool takeoff_sent;
    {
        std::lock_guard lk(mtx_);
        s = st_;
        takeoff_sent = takeoff_sent_;
    }
    const auto& c = in.cmd;
    const bool deselected_now = was_selected_ and not in.selected;
    was_selected_ = in.selected;

    if (not in.selected)
    {
        // B in flight: stop the last velocity now (GUIDED would otherwise keep it for its 3 s timeout).
        if (deselected_now and s.armed and s.mode == kGuided) velocity(0, 0, 0, 0);
        return;
    }

    if (not s.armed)
    {
        // Climb stick on the ground = take off. GUIDED first, then arm; the take-off goes once armed.
        if (c.vz > cfg_.stick_arm and now - last_arm_try_ > std::chrono::seconds(2))
        {
            last_arm_try_ = now;
            set_mode(kGuided);
            command_long(MAV_CMD_COMPONENT_ARM_DISARM, 1);
            std::print("[pilot] take-off requested (GUIDED, arm, {:.1f} m)\n", cfg_.takeoff_alt_m);
        }
        return;
    }

    if (s.mode == kLand)
    {
        if (c.vz > cfg_.stick_arm and now - last_mode_try_ > std::chrono::seconds(1))
        {
            last_mode_try_ = now;
            set_mode(kGuided);                                    // pilot aborts the landing
            std::print("[pilot] landing aborted by the pilot\n");
        }
        return;
    }
    if (s.mode != kGuided) return;                                // some other mode: leave it to the autopilot

    if (not takeoff_sent)
    {
        command_long(MAV_CMD_NAV_TAKEOFF, 0, 0, 0, 0, 0, 0, static_cast<float>(cfg_.takeoff_alt_m));
        std::print("[pilot] TAKEOFF to {:.1f} m\n", cfg_.takeoff_alt_m);
        std::lock_guard lk(mtx_);
        takeoff_sent_ = true;
        return;
    }
    // Let the take-off finish: a velocity setpoint in GUIDED replaces the take-off target. Without the landed state
    // (stream not flowing yet) there is no way to know it finished, so wait for it too.
    if (s.landed != MAV_LANDED_STATE_IN_AIR) return;

    // Held "down" close to the ground: hand over to LAND (descend, touch down, disarm — the autopilot's job).
    if (c.vz < -cfg_.stick_land and s.rel_alt_m < cfg_.land_alt_m and now - last_mode_try_ > std::chrono::seconds(1))
    {
        last_mode_try_ = now;
        set_mode(kLand);
        std::print("[pilot] LAND at {:.2f} m\n", s.rel_alt_m);
        return;
    }
    // Our command: forward, LEFT, UP, yaw CCW. ArduPilot's body frame: forward, RIGHT, DOWN, yaw CW.
    velocity(c.vx, -c.vy, -c.vz, -c.yaw_rate);
}

void MavlinkPilot::run()
{
    auto last_hb = clock::time_point{}, last_tick = clock::time_point{}, last_retry = clock::time_point{};
    mavlink_message_t msg;
    mavlink_status_t mst{};
    while (not stop_)
    {
        const auto now = clock::now();
        if (fd_ < 0)
        {
            {
                std::lock_guard lk(mtx_);
                st_.connected = false;
            }
            if (now - last_retry < std::chrono::seconds(1)) { std::this_thread::sleep_for(std::chrono::milliseconds(100)); continue; }
            last_retry = now;
            if (not connect()) continue;
            std::print("[pilot] MAVLink connected to ArduPilot at {}:{}\n", cfg_.host, cfg_.port);
            std::lock_guard lk(mtx_);
            st_.connected = true;
        }
        if (now - last_hb > std::chrono::seconds(1))
        {
            last_hb = now;
            mavlink_message_t hb;
            mavlink_msg_heartbeat_pack(kSys, kComp, &hb, MAV_TYPE_ONBOARD_CONTROLLER, MAV_AUTOPILOT_INVALID, 0, 0, 0);
            send(&hb);
            // Ask for the two streams the logic needs (5 Hz) — and again while they do not flow: a request sent
            // while the autopilot is still booting is lost, and without them the pilot cannot tell a take-off
            // from a hover.
            clock::time_point last_state;
            {
                std::lock_guard lk(mtx_);
                last_state = last_state_msg_;
            }
            if (now - last_state > std::chrono::seconds(2) and now - last_stream_req_ > std::chrono::seconds(2))
            {
                last_stream_req_ = now;
                command_long(MAV_CMD_SET_MESSAGE_INTERVAL, MAVLINK_MSG_ID_EXTENDED_SYS_STATE, 200000);
                command_long(MAV_CMD_SET_MESSAGE_INTERVAL, MAVLINK_MSG_ID_GLOBAL_POSITION_INT, 200000);
            }
        }
        if (now - last_tick > std::chrono::milliseconds(50))     // 20 Hz setpoints
        {
            last_tick = now;
            tick(input_(), now);
        }
        pollfd p{fd_, POLLIN, 0};
        if (fd_ >= 0 and ::poll(&p, 1, 10) > 0)
        {
            std::uint8_t buf[2048];
            const ssize_t n = ::recv(fd_, buf, sizeof(buf), 0);
            if (n <= 0) { ::close(fd_); fd_ = -1; std::print("[pilot] MAVLink link lost\n"); continue; }
            for (ssize_t i = 0; i < n; ++i)
                if (mavlink_parse_char(MAVLINK_COMM_0, buf[i], &msg, &mst))
                    handle(&msg);
        }
    }
}

}  // namespace drone
